    30→            power_reduction_percent: 0.0,
    31→            battery_extension_ratio: 1.0,
    32→            dvfs_latency_ms: 0,
    33→            consensus_latency_ms: 0,
    34→            sleep_entry_latency_us: 0,
    35→            pattern_accuracy_percent: 0.0,
    36→            prediction_error_percent: 0.0,
    37→            failover_latency_ms: 0,
