    41→    pub fn all_rules_passed(&self) -> bool {
    42→        self.power_reduction_percent >= 40.0 &&
    43→        self.battery_extension_ratio >= 2.0 &&
    44→        self.dvfs_latency_ms < 10 &&
    45→        self.consensus_latency_ms < 150 &&
    46→        self.sleep_entry_latency_us < 5000 &&
    47→        self.pattern_accuracy_percent >= 85.0 &&
    48→        self.prediction_error_percent <= 10.0 &&
    49→        self.failover_latency_ms < 50
    50→    }
    51→
    52→    pub fn rules_passed_count(&self) -> u32 {
    53→        let mut count = 0;
    54→        if self.power_reduction_percent >= 40.0 { count += 1; }
    55→        if self.battery_extension_ratio >= 2.0 { count += 1; }
    56→        if self.dvfs_latency_ms < 10 { count += 1; }
    57→        if self.consensus_latency_ms < 150 { count += 1; }
    58→        if self.sleep_entry_latency_us < 5000 { count += 1; }
    59→        if self.pattern_accuracy_percent >= 85.0 { count += 1; }
    60→        if self.prediction_error_percent <= 10.0 { count += 1; }
    61→        if self.failover_latency_ms < 50 { count += 1; }
    62→        count
    63→    }
