    81→pub struct GreenDistributedFabric {
    82→    pub l1_power: PowerSensingLayer,
    83→    pub l2_scheduler: GreenSchedulerLayer,
    84→    pub l3_predictor: PredictivePMLayer,
    85→    pub l4_consensus: GreenConsensusLayer,
    86→    pub l5_learning: EnergyHistoryLayer,
    87→    pub metrics: GreenFabricMetrics,
    88→    pub operational_since_ms: u64,
    89→    pub cycles_executed: u32,
    90→}
